<?php require_once __DIR__.'/chart_local.php'; function reqplot($width=550,$height=400){$r=db_query("SELECT entries,UNIX_TIMESTAMP(date) FROM request_history WHERE date>=DATE_SUB(NOW(),INTERVAL 2 WEEK) ORDER BY date","ro");$p=[];while($x=mysqli_fetch_row($r))$p[]=[date('m-d',(int)$x[1]),(float)$x[0]];echo '<div id="reqchart_div">'.atlas_chart_line($p,'Installation Requests',$width,$height).'</div>';}
